import json
from pathlib import Path
root=Path(__file__).resolve().parents[2]
prior=json.loads((root/'experiments/design-readiness-20261104/decision-feature-map.json').read_text())
# Each row describes a variant, not a promise that every instance of the mechanism requires QAT.
rows=[
('Q01','Trainable binary signs and learned row scales','include','Learn the actual binary function instead of freezing a rounded checkpoint. Scale-only control remains useful.','scales,signs','ParetoQ','Full-sign modern DFlash training remains unqualified; scale adaptation has prior local evidence.'),
('Q02','Learned input-channel scales plus output-row scales','test','Give binary projections channel-dependent amplitudes with two small vectors.','input','OneBit','Additional input scaling changes activation codes; not safely folded through rounding.'),
('Q03','Learned within-row group scales','test','Give groups of connections independently trained strengths.','groups','GPTQ','Extra scale loads and scaled partial sums; prior grouping+rotation experiments confounded.'),
('Q04','Learned binary centers and projection bias','later','Asymmetric binary values and/or a learned output offset.','input','FBI-LLM','Weight center times sum of inputs is not the same operation as a constant output bias.'),
('Q05','Adapt existing normalization gains; optional extra normalization or residual gains','test','Let scale and branch balance adapt to quantization. Additional normalization is a separate architecture trial.','norms','OneBit','Do not claim existing DFlash RMSNorm/residual connections as additions.'),
('Q06','Learned activation clipping and step sizes','test','Learn range and rounding-grid spacing; optionally learn asymmetric offsets.','input','PACT,LSQ','PACT originated in vision; signed SiLU inputs need an appropriate signed quantizer, not copied nonnegative PACT.'),
('Q07','Training-integrated transforms','test','Use an online Hadamard or learned rotation/affine transform before selected low-bit projections and adapt the model to it.','input','BitNet v2,SpinQuant,FlatQuant','Fixed Hadamard has no trainable parameters itself. Inserting it into a strict-W1 graph still needs compatible reparameterization or adaptation; BitNet v2 is ternary.'),
('Q08','Task-trained low-rank correction','later','Add a small high-precision residual projection and train it on draft predictions.','corrections','SVDQuant','Local reconstruction and native-prefix improvements did not reliably improve full requests in old backlog.'),
('Q09','Task-trained sparse outlier correction','later','Spend higher precision on selected connections or channels that binary weights cannot represent well.','sparse','PB-LLM','Index/gather/kernel costs and added payload must be counted.'),
('Q10','Extra binary planes with learned amplitudes and residual-aware training','later','Add selective binary residual contributions; discourage different planes from learning the same correction.','planes','RaBiT','More than one bit per selected connection. RaBiT coupled paths require a new training implementation, not just extra independent weights.'),
('Q11','Activation sparsification trained in the forward pass','later','Teach the model to tolerate dropping small activations; combine with A4/A8 where appropriate.','input','BitNet a4.8,Q-Sparse','Zeros in a dense tensor do not automatically save GPU time. Literature precedent largely ternary.'),
('Q12','Target-distribution distillation','test','Train against probabilities from the exact intended target; test CE/KL combinations and temperature.','distillation','FBI-LLM,BitDistiller','Conditional shortlist mass must not be confused with full-vocabulary probabilities; no local modern KD win established.'),
('Q13','Block/output or intermediate-feature reconstruction auxiliaries','later','Use aligned higher-precision outputs as temporary training guidance.','distillation','OneBit','Hidden representations need not remain identical after binary adaptation; do not replace target-probability supervision with hidden MSE.'),
('Q14','Verification-aware and expected-progress losses','test','Compare VAT, EAL/WTV or EDR against base DFlash loss, matching greedy versus sampling semantics.','objectives','VAT,EAL,EDR','Base DFlash already weights early positions. Recent simple depth weighting/smoothing did not establish local extra speed.'),
('Q15','Serving-state replay, balanced coverage and prefix/margin retention','include','Adapt on correct native histories and representative domains; replay successful prefixes while learning failures.','data','DFlash','Data fidelity is required; replay weighting and margin protection are experiments, not demonstrated universal gains.'),
('Q16','Quantizer-aware gradients, latent initialization and parameter-group learning rates','include','Explicitly choose straight-through/scale-gradient rules and separate sign/scale/norm update policies.','signs','ParetoQ,EWGS','Use a simple reproducible control; alternative estimators are trials, with vision versus LLM evidence distinguished.'),
('Q17','Oscillation damping, selective freezing and stability schedules','later','Reduce unproductive sign flipping only when diagnostics identify it.','signs','Oscillations,Bop','CNN evidence does not establish a transformer gain; full EMA parameter averaging can change binary signs.'),
('Q18','Precision/coverage curricula','test','Compare direct final-precision training with staged W1 coverage or A8-to-A4 adaptation.','signs','BitNet v2,ParetoQ','Charge all stages; curriculum is not automatically better than direct training.'),
('Q19','Learned acceptance/confidence predictor','later','Predict useful proposal length rather than relying only on logit gaps.','policy','DSpark','Can fit an auxiliary head separately; trained component, not a mandatory full-model QAT run.'),
('Q20','Token-conditioned correction: Markov or contextual candidate scoring','later','DSpark-style sequential adjustment or DCOCO-style parallel scoring of adjacent candidate pairs.','corrections','DSpark,DCOCO','Not a validated gain for W1 or our modern baseline. DCOCO scoring is parallel; path selection still follows predecessors.'),
('Q21','Learned head compression or candidate selection','later','Train a factorized head, reduced-vocabulary head or shortlist predictor.','heads','DFlash','A frozen subset or SVD approximation can be tested without QAT; learned recovery belongs here.'),
('Q22','Alternative fusion/tap selection and width/depth adaptation','later','Train a revised target-feature interface or resized draft body if capacity is the bottleneck.','corrections','DFlash','Normal feature fusion/KV injection already exist. Changed taps and shape need new captures and export contract.'),
('Q23','Binary factorization, binary experts or learned binary codecs','defer','Alternative representation families such as LittleBit factors, mixture routing, BTC-LLM codebooks or BiSCo decoders.','multibinary','LittleBit,BTC-LLM,BiSCo','Not plain one-plane W1 matrix multiplication; total factors/decoder/routing cost matters.'),
('Q24','Alternative binary optimizers and reduced training state','defer','Bop or recent error-diffusion updates avoid ordinary full-precision latent/Adam state.','signs','Bop,ErrorDiffusion','Training-resource research, not inference feature; recent ED evidence is on much smaller language models.'),
('I01','Selective W1 coverage and protected operations','include','Keep an explicit precision map: FFN, attention, fusion, head/embedding, norm/residual, accumulator and KV precision separately.','precision','','No learned selector required. Restoring weights after adaptation is not guaranteed to preserve behavior.'),
('I02','Per-operation A8/A4 and scale granularity','include','Start an A8 reference; independently screen per-token, group-wise and mixed precision quantizers.','input','BitNet a4.8','Selecting a policy needs no QAT, but an adapted final model should train with its chosen policy.'),
('I03','Fixed or calibrated clipping, scaling and code grids','test','Absmax/absmean/percentile or calibration-search scales, symmetric/asymmetric grids and explicit zero-point treatment.','input','PACT,BitNet v2','No parameter gradient required for these variants. They can alter acceptance and need native testing.'),
('I04','Data-aware binary initialization and row-orientation rescue','include','Fit signs/scales to representative inputs before QAT; correct negatively correlated zero-scale row orientation.','scales,signs','ARB-LLM,BiLLM,PB-LLM','Use calibrated reconstruction rather than assuming smaller weight error means better proposal choices.'),
('I05','Fixed group scales, affine corrections and fixed extra planes','test','Analytic/calibrated representation controls before learning their parameters.','groups,planes,input','BiLLM,ARB-LLM','Representation variants require native kernels. Independent of QAT does not mean a zero-work kernel switch.'),
('I06','Fixed rotations, channel equalization and post-training transform fitting','test','Explore QuaRot/SmoothQuant and fitted SpinQuant/FlatQuant preprocessing as distinct variants.','input','QuaRot,SmoothQuant,SpinQuant,FlatQuant','Fitted variants require optimization, but not full drafter QAT. Folding a general rotation/column gain into W1 does not preserve the binary format.'),
('I07','Post-training low-rank or sparse correction','later','SVD/calibration-fit a residual, or keep selected outliers in higher precision, without task-QAT.','corrections,sparse','SVDQuant,PB-LLM','SVDQuant is image-diffusion W4A4 evidence, not binary DFlash validation; correction fusion is important.'),
('I08','Post-training factorization and capacity allocation','later','AF1-like factorization and sensitivity allocation as an alternate initializer/control.','multibinary','AF1','Not optimization-free: AF1 includes global learned-scale reconstruction. Does not use the plain single-sign-matrix representation.'),
('I09','Shape-specific kernel dispatch','include','Use measured integer Tensor Core path as reference, with DP4A or other kernels only where actual shapes justify them.','runtime','','Current local native A8 default wins screened methods on old DSpark/Qwen3-F16; no blanket binary-math advantage.'),
('I10','Prepacking, shared quantization and fused kernels','include','Avoid repeated immutable transposes/unpacking; reuse compatible gate/up inputs; fuse norm/quantization, gate operations, scales and residual epilogues when legal.','runtime','','A graph/rounding change still needs numerical and acceptance checks; no new speed measured in this survey.'),
('I11','CUDA graphs, buffers and synchronization reduction','include','Reduce launch/allocation overhead, keep temporary data resident and batch compatible projections.','runtime','','Profile first; existing optimizations may already cover part of this.'),
('I12','Compact output extraction and head execution','include','GPU argmax/top-k, avoid unused logit transfers, exploit supported batched/shared-head execution.','runtime,heads','','Full-vocabulary transfer elimination already exists on some prior paths; do not count it again as new.'),
('I13','Context K/V reuse and minimal target-feature catch-up','include','Avoid computing context queries/FFN/head outputs that are truly unused; preserve all required cache and feature updates.','runtime','','DFlash already injects/caches context; optimization concerns redundant work, not removing required semantics.'),
('I14','Training-system efficiency independent of recipe','include','Cached frozen features, chunked K/V-only context, batched heads, efficient optimizer kernels and activation checkpointing.','runtime','','Must preserve update/mask/data semantics; caching invalid after incompatible target/prefix/tap changes. No training-state compression equivalence assumed.'),
('I15','Static/adaptive proposal-length and confidence-gap policies','test','Choose block/prefix length from measured cost and existing logits or acceptance history.','policy','','Discarding computed slots does not save their draft compute; cost target verification separately.'),
('I16','Static or heuristic dynamic vocabulary shortlists','later','Score selected output rows using a deterministic proposal policy without training a selector.','heads','','Top-k after full-head scoring saves no head matmul. Missing token support can lower acceptance; target verifier remains full and correct.'),
('I17','Beam/tree proposals, retries and suffix reuse','later','Use multiple candidates or reuse draft material under correctly conditioned verification.','tree,policy','','No automatic quality benefit; branch masks/KV rollback and valid sampling probabilities required; unchanged greedy retries repeat themselves.'),
('I18','Drafter-side KV/cache quantization','later','Compress draft context memory when its cost is material.','runtime','KIVI,TurboQuant','Keep target/verifier precision fixed. Cache arithmetic changes can reduce acceptance; published long-context gains are not our short-block gains.'),
('I19','Structural pruning/slicing or frozen head factorization','defer','Try coupled gate/up/down channel slicing or SVD head compression as no-QAT controls.','heads','','Recovery training is a separate QAT variant; sparse/pruned sizes must suit actual kernels.'),
('I20','Per-stage and per-position diagnostics','include','Measure quantization zeros/outliers, sign flips, accepted-prefix survival, packing/draft/head/verification time and total request speed.','diagnostics','','Instrumentation and selection support, not a model quality feature; local proxy improvements alone cannot promote a candidate.')]
sources={
'ParetoQ':'https://arxiv.org/html/2502.02631v1','OneBit':'https://arxiv.org/html/2402.11295v1','GPTQ':'https://arxiv.org/html/2210.17323v2','FBI-LLM':'https://arxiv.org/html/2407.07093v1','PACT':'https://arxiv.org/abs/1805.06085','LSQ':'https://arxiv.org/abs/1902.08153','BitNet v2':'https://arxiv.org/html/2504.18415v1','SpinQuant':'https://arxiv.org/abs/2405.16406','FlatQuant':'https://arxiv.org/abs/2410.09426','SVDQuant':'https://hanlab.mit.edu/projects/svdquant','PB-LLM':'https://arxiv.org/abs/2310.00034','RaBiT':'https://arxiv.org/html/2602.05367v1','BitNet a4.8':'https://arxiv.org/abs/2411.04965','Q-Sparse':'https://arxiv.org/abs/2407.10969','BitDistiller':'https://arxiv.org/abs/2402.10631','VAT':'https://arxiv.org/abs/2608.30135','EAL':'https://arxiv.org/abs/2609.24150','EDR':'https://arxiv.org/abs/2610.10411','DFlash':'https://arxiv.org/html/2602.06036v2','EWGS':'https://arxiv.org/abs/2104.00903','Oscillations':'https://proceedings.mlr.press/v162/nagel22a.html','Bop':'https://arxiv.org/abs/1906.02107','DSpark':'https://arxiv.org/abs/2607.05147','DCOCO':'https://arxiv.org/html/2610.12570v1','LittleBit':'https://arxiv.org/abs/2506.13771','BTC-LLM':'https://aclanthology.org/2026.acl-long.1066/','BiSCo':'https://arxiv.org/abs/2607.08643','ErrorDiffusion':'https://arxiv.org/abs/2610.34566','ARB-LLM':'https://arxiv.org/html/2410.03129v1','BiLLM':'https://arxiv.org/abs/2402.04291','QuaRot':'https://arxiv.org/abs/2404.00456','SmoothQuant':'https://arxiv.org/abs/2211.10438','AF1':'https://arxiv.org/html/2609.06161v1','KIVI':'https://arxiv.org/abs/2402.02750','TurboQuant':'https://research.google/blog/turboquant-redefining-ai-efficiency-with-extreme-compression/'}
items=[]
for id,name,priority,mechanism,backlog,refs,limit in rows:
 items.append(dict(id=id,name=name,group='training_dependent_variant' if id[0]=='Q' else 'independent_of_full_qat_variant',recommendation=priority,mechanism=mechanism,backlog_mechanisms=backlog.split(','),source_ids=refs.split(',') if refs else [],qualification=limit))
mechanism_alias={'sparse':'sparse','runtime':'runtime','policy':'policy','tree':'tree','multibinary':'multibinary'}
# Preserve the original namespaces and provenance, rather than claiming 130 independent tests.
backlog=[dict(id=f['id'],name=f['name'],mechanism_id=f['mechanism_id']) for f in prior['supplemental_feature_map']]
families=[dict(family_id=f['family_id'],mechanism_id=f['mechanism_id'],canonical_segment_ids=f['canonical_segment_ids']) for f in prior['family_map']]
out=dict(date='2026-11-04',scope='Design discussion and literature/backlog inventory only. No GPU work, training, model change or selected architecture extras.',starting_point='Plain DFlash; user-selected W1 and activations above one bit; modern DFlash Q4_K_M remains baseline.',classification={'Q':'Chosen learned/task-adapted variant belongs in QAT or auxiliary training. Not a claim that the generic mechanism mathematically requires end-to-end QAT.','I':'Can be screened or applied without full task-QAT. Calibration or small optimization is explicitly disclosed; independence does not promise preserved acceptance.'},priorities={'include':'Proposed reference capability or engineering principle, not approved implementation.','test':'Priority ablation, not bundled default.','later':'Conditional on measured quality/cost need.','defer':'Different representation/architecture or weak applicability.'},items=items,sources=sources,backlog_F01_F32=backlog,backlog_34_recipe_families=families,local_evidence=['experiments/design-readiness-20261104/decision-feature-map.md','experiments/design-readiness-20261104/readiness.md','experiments/binary-screen-20261104/README.md','experiments/binary-methods-20261104/README.md'],evidence_cautions=['98 segments and 32 feature IDs overlap; they are not 130 independent experiments.','Modern prior scale-only result is EAGLE-family, not evidence for trained modern W1 DFlash.','Recent depth/smoothing arms established no extra throughput gain; many older tests were short and raw assets partially missing.','Modern activation screen was a small frozen-A8-weight probe, not equal-QAT/native evidence.','Native kernel comparison was old Qwen3 F16/DSpark, not modern target matrix.','BitNet v2 and a4.8 use ternary weights; OneBit uses floating activations in its reported binary-weight architecture.','PrismML public announcement checked; linked whitepaper unavailable through web fetch, no proprietary training recipe inferred.'],baseline_not_additions=['DFlash feature fusion and per-layer context KV injection','Existing residual paths, attention, normalization, shared frozen head/embeddings','DFlash original early-position loss weighting'],search_branches=['Binary parameterizations and QAT','Activation quantizers/outliers/rotations/sparsity','PTQ initialization and representation exceptions','Gradient/stability/optimizer/training resources','Speculative loss/data/correction/policy','Head/cache/kernel/packing/runtime'],search_stop='Multiple passes across current LLM, older BNN, PTQ and speculative literature converge on the mechanism families listed. New codebook/factor/optimizer leads retained as deferred branches. No claim of exhaustive literature or proved gains on our candidate.',unadopted_branches=['W1A1 thresholds/parallel retries/tree work remains future track, not current >1-bit recipe.','Ternary/two-bit controls change weight alphabet; retain as diagnostic alternatives, not label as strict W1.','Binary-code compression with neural decoder is not direct sign-matrix arithmetic.'])
assert len(backlog)==32 and len(families)==34
assert len({x['id'] for x in items})==44
assert all(s in sources for x in items for s in x['source_ids'])
Path(__file__).with_name('inventory.json').write_text(json.dumps(out,indent=2)+'\n')
print('44 variants; 32 historical feature IDs; 34 recipe families; source references resolved')
